import fs from 'node:fs';
import crypto from 'node:crypto';
import zlib from 'node:zlib';
import {execFileSync} from 'node:child_process';
const archive='/Users/sourceborn/Documents/ChatGPT/Ash/V01-2026-09-07/payload/raw-assets/AM.07.Parameter.Files.zip';
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const rawArchive=fs.readFileSync(archive);
if(sha(rawArchive)!=='652be4ddb2b40915543ad848b2bfa10d011c6c2c5723a6e6a3480a85ddb2e2e5')throw Error('Archive pin mismatch');
const counts = values => Object.fromEntries([...values.reduce((m,v)=>m.set(String(v),1+(m.get(String(v))||0)),new Map())].sort((a,b)=>a[0].localeCompare(b[0])));
const duplicates = (rows,key) => {
 const groups=new Map(); for (const row of rows) { const k=key(row); groups.set(k,[...(groups.get(k)||[]),row]); }
 const repeated=[...groups].filter(([,rs])=>rs.length>1);
 return {unique:groups.size,duplicate_groups:repeated.length,excess_records:repeated.reduce((s,[,rs])=>s+rs.length-1,0),examples:repeated.slice(0,12).map(([key,rs])=>({key,count:rs.length,records:rs.slice(0,3)}))};
};
const isinValid = value => {
 if(!/^[A-Z]{2}[A-Z0-9]{9}\d$/.test(value))return false;
 const digits=[...value].map(c=>/[A-Z]/.test(c)?String(c.charCodeAt(0)-55):c).join('');
 return [...digits].reverse().reduce((s,c,i)=>{let n=Number(c)*(i%2?2:1);return s+Math.floor(n/10)+n%10;},0)%10===0;
};
const numericFields=['lot_size','freeze_quantity','minimum_lot','tick_size','qty_multiplier','strike_price','expiry','last_trading_date','intraday_margin','intraday_leverage'];
const requested=['BBL','LATENTVIEW','JWL','RAILTEL','KEC','TRANSRAILL','GODFRYPHLP','BSOFT','ZENSARTECH','RHIM','SURYAROSNI','THERMAX'];
const result={schema_version:'ashstocks-am07-instrument-content-v1',audit_date:'2026-09-28',review_commit:'910c72f1ab6fdf014c081746626f38e2fe029759',archive:{path:archive,bytes:rawArchive.length,sha256:sha(rawArchive)},method:{full_gzip_decode:true,full_json_parse:true,all_records_and_fields_visited:true,raw_modified:false,provider_fetches:0,mongo_operations:0,app_runtime_executed:false},members:[]};
const datasets={};
for(const name of ['NSE.json.gz','BSE.json.gz','BSE_MIS.json.gz']){
 const member='AM 07 Parameter Files/'+name;
 const compressed=execFileSync('unzip',['-p',archive,member],{maxBuffer:5000000});
 const raw=zlib.gunzipSync(compressed),value=JSON.parse(raw.toString('utf8'));
 const rows=Array.isArray(value)?value:Object.values(value);
 if(!Array.isArray(value)||rows.some(r=>!r||Array.isArray(r)||typeof r!=='object'))throw Error('Unexpected record shape');
 datasets[name]=rows;
 const fields={};for(const r of rows)for(const [k,v] of Object.entries(r)){
  const f=fields[k] ||= {present:0,null:0,empty_string:0,types:{}};
  f.present++;if(v===null)f.null++;if(v==='')f.empty_string++;
  const t=v===null?'null':Array.isArray(v)?'array':typeof v;f.types[t]=(f.types[t]||0)+1;
 }
 for(const f of Object.values(fields))f.absent=rows.length-f.present;
 const numeric={};for(const k of numericFields){const vs=rows.filter(r=>Object.hasOwn(r,k)).map(r=>r[k]);if(!vs.length)continue;
  const ns=vs.filter(v=>typeof v==='number'&&Number.isFinite(v));
  numeric[k]={present:vs.length,finite_numbers:ns.length,non_numeric:vs.length-ns.length,zero:ns.filter(n=>n===0).length,negative:ns.filter(n=>n<0).length,min:Math.min(...ns),max:Math.max(...ns)};
  if(['expiry','last_trading_date'].includes(k))numeric[k].diagnostic_unix_ms_range=[Math.min(...ns),Math.max(...ns)].map(n=>new Date(n).toISOString());
 }
 const cash=rows.filter(r=>String(r.segment).endsWith('_EQ'));
 const malformedKeys=rows.filter(r=>typeof r.instrument_key!=='string'||!r.instrument_key.startsWith(r.segment+'|'));
 const isinRows=rows.filter(r=>Object.hasOwn(r,'isin'));
 const invalidIsins=isinRows.filter(r=>!isinValid(r.isin));
 const identityMismatches=cash.filter(r=>r.instrument_key!==r.segment+'|'+r.isin);
 result.members.push({member,bytes:compressed.length,sha256:sha(compressed),uncompressed_bytes:raw.length,uncompressed_sha256:sha(raw),root_type:'array',records:rows.length,field_value_count:Object.values(fields).reduce((s,f)=>s+f.present,0),fields,segment_counts:counts(rows.map(r=>r.segment)),exchange_counts:counts(rows.map(r=>r.exchange)),segment_instrument_type_counts:counts(rows.map(r=>r.segment+'/'+r.instrument_type)),numeric,
  instrument_keys:duplicates(rows,r=>r.instrument_key),segment_exchange_tokens:duplicates(rows,r=>r.segment+'|'+r.exchange_token),
  malformed_key_prefix:{count:malformedKeys.length,examples:malformedKeys.slice(0,5)},
  isin_syntax_and_luhn:{present:isinRows.length,valid:isinRows.length-invalidIsins.length,invalid:invalidIsins.length,prefix_counts:counts(isinRows.map(r=>String(r.isin).slice(0,3))),invalid_examples:invalidIsins.slice(0,8),authority:'Diagnostic syntax/check-digit only; not proof of listing or company membership'},
  cash_identity:{records:cash.length,key_isin_mismatches:identityMismatches.length,mismatch_examples:identityMismatches.slice(0,8),symbols:duplicates(cash,r=>r.trading_symbol)},
  diagnostic_dates_are_not_fetch_dates:true,
  requested_stocks:requested.map(symbol=>({requested_symbol:symbol,matches:cash.filter(r=>r.trading_symbol===symbol).map(r=>({instrument_key:r.instrument_key,isin:r.isin,trading_symbol:r.trading_symbol,name:r.name,short_name:r.short_name,instrument_type:r.instrument_type,lot_size:r.lot_size,tick_size:r.tick_size}))}))});
}
const nse=datasets['NSE.json.gz'], bse=datasets['BSE.json.gz'], mis=datasets['BSE_MIS.json.gz'];
const candidates=nse.filter(r=>r.exchange==='NSE'&&r.segment==='NSE_EQ'&&r.instrument_type==='EQ');
result.nse_eq_eq_candidate_diagnostics={count:candidates.length,distinct_symbols:new Set(candidates.map(r=>r.trading_symbol)).size,distinct_isins:new Set(candidates.map(r=>r.isin)).size,isin_prefix_counts:counts(candidates.map(r=>r.isin?.slice(0,3))),security_type_counts:counts(candidates.map(r=>r.security_type)),symbol_syntax_failures:candidates.filter(r=>!/^[A-Z0-9][A-Z0-9&._-]{0,49}$/.test(r.trading_symbol)).length,isin_syntax_failures:candidates.filter(r=>!/^IN[A-Z0-9]{10}$/.test(r.isin)).length,key_isin_mismatches:candidates.filter(r=>r.instrument_key!=='NSE_EQ|'+r.isin).length,checksum_failures:candidates.filter(r=>!isinValid(r.isin)).map(r=>({symbol:r.trading_symbol,isin:r.isin})),fund_prefix_symbols:candidates.filter(r=>r.isin?.startsWith('INF')).map(r=>r.trading_symbol),test_named_records:candidates.filter(r=>/DUMMY|TEST/i.test(r.name+' '+r.trading_symbol)),current_nse_company_membership:'UNVERIFIED: contemporaneous authoritative EQUITY_L.csv is not paired with this snapshot',current_suspension_status:'UNVERIFIED: contemporaneous suspension source is not paired with this snapshot',eligible_universe_count:null};
const bseByKey=new Map(bse.map(r=>[r.instrument_key,r]));const differingFields={}, missing=[],different=[];
for(const r of mis){const match=bseByKey.get(r.instrument_key);if(!match){missing.push(r);continue;}
 const diffs=[];for(const k of new Set([...Object.keys(r),...Object.keys(match)])){if(['intraday_margin','intraday_leverage'].includes(k))continue;
  if(JSON.stringify(r[k])!==JSON.stringify(match[k])){diffs.push({field:k,mis:r[k]??null,master:match[k]??null});differingFields[k]=(differingFields[k]||0)+1;}}
 if(diffs.length)different.push({instrument_key:r.instrument_key,trading_symbol:r.trading_symbol,differences:diffs});
}
const residuals=mis.map(r=>Math.abs(r.intraday_margin*r.intraday_leverage-100));
result.bse_mis_crosscheck={mis_records:mis.length,matched_master_keys:mis.length-missing.length,unmatched:missing,matching_records_with_field_differences:different.length,differing_field_counts:differingFields,difference_examples:different.slice(0,12),margin_leverage_pairs:counts(mis.map(r=>r.intraday_margin+'/'+r.intraday_leverage)),margin_times_leverage_equal_100_at_1e_9:residuals.filter(n=>n<=1e-9).length,max_absolute_product_residual:Math.max(...residuals),meaning:'Historical broker intraday-product eligibility, not complete BSE cash membership, current permission, or overnight position sizing'};
const bseCash=bse.filter(r=>r.segment==='BSE_EQ');const bseByIsin=new Map();for(const r of bseCash){const rs=bseByIsin.get(r.isin)||[];rs.push(r);bseByIsin.set(r.isin,rs);}
result.cross_exchange_isin_diagnostics={nse_eq_eq_candidates:candidates.length,with_bse_eq_isin_match:candidates.filter(r=>bseByIsin.has(r.isin)).length,without_bse_eq_isin_match:candidates.filter(r=>!bseByIsin.has(r.isin)).length,rule:'Same ISIN is cross-exchange security evidence only; NSE and BSE instrument keys, ticks, series and tradability remain exchange-specific'};
result.transrail_name_resolution=Object.fromEntries(Object.entries(datasets).map(([k,rs])=>[k,rs.filter(r=>r.segment.endsWith('_EQ')&&/TRANSRAIL/i.test(r.name+' '+r.trading_symbol))]));
const repo='/Users/sourceborn/Documents/ChatGPT/Ash/AshStocks';
result.scoped_consumers=[{path:'lib/official-nse-master.mjs',role:'Current pure validators and fresh-provider loader; NSE_EQ/EQ selection must also intersect official NSE company symbol+ISIN membership and current suspensions. Archive master alone is insufficient.'},{path:'server-official-nse-master-patch.mjs',role:'Current source loader fetches fresh sources and saves universe metadata with revision increment, invalidates scan cache and records suspension metadata. Does not read the preserved archive.'}].map(s=>({...s,sha256:sha(fs.readFileSync(repo+'/'+s.path))}));
const pure=await import(repo+'/lib/official-nse-master.mjs');
try{pure.buildOfficialNseUniverse(nse,[]);throw Error('Unexpected missing-membership acceptance');}catch(e){if(e.code!=='official_nse_membership_required')throw e;result.pure_missing_membership_probe={error_code:e.code,suspension_rows_supplied:0,membership_supplied:false,external_calls:0,meaning:'Negative offline validation probe only; the empty suspension list is not current suspension evidence'};}
result.authority_and_limits=[
 'Full serialized content review is not authorization to import or deploy. No current-provider master, official membership or suspension data was fetched.',
 'No source retrieval timestamp/HTTP Last-Modified accompanies these records. Archive modification time, contract expiry and current documentation do not establish snapshot freshness.',
 '2376 NSE_EQ/EQ candidates include 328 INF-prefixed fund identities. The remaining 2048 identities are not automatically 2048 eligible company stocks; exact dated NSE membership and suspensions are still required.',
 'BSE group codes A/B/etc are not NSE EQ-series codes. Do not apply NSE-specific type filtering to BSE data.',
 'The master stores instrument identity and trading metadata, not OHLCV, live quotes, EPS/P/E, news, institutional flows or portfolio state.',
 'Do not normalize ticker names, units, prices or historic ISINs silently. Corporate-action-aware dated mapping is required for candle joins.',
 'Raw tick_size values are preserved. The audited source does not establish the currency/unit conversion needed for a pricing consumer.',
 'Syntax/Luhn failures are diagnostic discrepancies, not authority to rewrite or delete source identities.',
 'All twelve user-requested companies have archived NSE_EQ/EQ matches after exact source name resolution of Transrail to TRANSRAILL; this is not current saved-universe proof.'
];
result.online_reference={url:'https://upstox.com/developer/api-documentation/instruments/',consulted_on:'2026-09-28',claims:['Use instrument_key as the unique identifier; exchange_token may be reused after expiry.','MIS files represent intraday-product availability, with intraday margin percentage and leverage.','BOD instruments are refreshed daily; an archived copy cannot establish current membership.'],scope:'Documentation consultation only; no provider data refresh'};
console.log(JSON.stringify(result,null,2));
